            // RT60 = time to decay 60 dB = -60 / slope
            val rt60 = (-60.0 / slope).toFloat()

            if (rt60 in 10f..10000f) {
                rt60PerBand[b] = rt60
                sumRt60 += rt60
                validBands++
            }
        }

        currentRt60Ms = if (validBands > 0) sumRt60 / validBands else currentRt60Ms
    }

