                cfg.copy(
                    targetSpl = info.recommendedSpl,
                    audioDelayMs = info.recommendedDelayMs
                )
            }
            _uiState.update {
                it.copy(audioDelayMs = info.recommendedDelayMs)
            }
        }
    }
}

